hority."}]}, {"id": "7b87da1c-4401-4098-97bd-dd1c8d744284", "type": "topic", "title": "Marxist, Social, and Labor History", "description": "This topic introduces materialist explanations and histories centered on class, labor, production, and social conflict.", "children": [{"id": "b9bedc30-7636-43a0-8ed8-c6223ba1a8e8", "type": "subtopic", "title": "Historical materialism", "children": [{"id": "efe32c3f-b48c-4193-b4d1-f85473b977ae", "type": "concept", "title": "mode of production"}, {"id": "bf63ae96-a087-4b4e-be25-9220d03af926", "type": "concept", "title": "class struggle"}, {"id": "d042dece-c571-49e9-910c-28296c45ed7a", "type": "concept", "title": "base and superstructure"}, {"id": "94b48597-c846-46ca-80b8-b03b2774d8a5", "type": "concept", "title": "capitalism"}, {"id": "f30fc3be-769b-4dd6-b282-17b0d3899488", "type": "concept", "title": "feudalism"}, {"id": "0ac901c5-a842-476e-bc33-fa9c74ac28c1", "type": "concept", "title": "ideology"}, {"id": "afbdac83-7b1b-4218-a532-f7b9e72d794e", "type": "concept", "title": "dialectic"}], "description": "Students learn how Marxist historians analyze social relations and structural change."}, {"id": "cf0e9a11-e3a2-4762-8dba-3a34474ea8e4", "type": "subtopic", "title": "Labor and working-class history", "children": [{"id": "e50df72e-a398-47a9-b32c-8897dc897d7c", "type": "concept", "title": "working class"}, {"id": "375eb073-69c8-488f-b955-058ac2a333ed", "type": "concept", "title": "labor movement"}, {"id": "ac8ccb93-b6ac-4820-abfd-fbcdf37a6a28", "type": "concept", "title": "strike"}, {"id": "41d1d5cd-e5ee-49a6-b08e-750ad962ac87", "type": "concept", "title": "union"}, {"id": "53ee4bc3-ca1d-48cc-854e-ef4982470c5b", "type": "concept", "title": "shop floor"}, {"id": "d3717004-2f80-4861-bc63-5361f912b2e2", "type": "concept", "title": "household labor"}, {"id": "e0ef9ef6-5a7c-406a-a2d0-e2bd60fa2685", "type": "concept", "title": "E. P. Thompson"}, {"id": "6acd30db-5fa4-4a0d-8d57-da65d59947c0", "type": "concept", "title": "agency"}], "desc